//! conformance — ORCH-R20 lane T11-a: run the sealed fixture battery
//! (`crossimpl/c/fixtures.txt`, generated by executing the JS reference
//! kernels — never this crate) against the Rust port and compare
//! byte-for-byte: final plane hash, event count, every event tuple
//! (tick, x, y, slot, resonance) and every term BIT PATTERN (float plane)
//! / term_q INTEGER (fixed plane).
//!
//! Mirrors `crossimpl/c/conformance.c` (the C lane's runner): same fixture
//! file, same line protocol, same output format, exit code = number of
//! failed cases (fail-loud). Stricter than the C runner by one field: the
//! event TICK is compared too (the fixtures record it; emission order
//! implies it, so a PASS here subsumes the C lane's tuple check).
//!
//! Usage: conformance <fixtures.txt>   (run from crossimpl/rs/)

use std::env;
use std::fs;
use std::io::{BufRead, BufReader};
use std::process::ExitCode;

use qthe::{vector_pass, Substrate};

/// Max plane bytes in the sealed battery (64×64) — the runner's documented
/// capacity envelope (planes are heap-allocated, so this is documentation,
/// not a limit).
#[allow(dead_code)]
const MAX_PLANE_BYTES: usize = 64 * 64;

fn hexval(c: u8) -> Option<u8> {
    match c {
        b'0'..=b'9' => Some(c - b'0'),
        b'a'..=b'f' => Some(c - b'a' + 10),
        b'A'..=b'F' => Some(c - b'A' + 10),
        _ => None,
    }
}

fn hex_to_bytes(hex: &[u8], n: usize) -> Option<Vec<u8>> {
    if hex.len() < 2 * n {
        return None;
    }
    let mut out = vec![0u8; n];
    for i in 0..n {
        let hi = hexval(hex[2 * i])?;
        let lo = hexval(hex[2 * i + 1])?;
        out[i] = (hi << 4) | lo;
    }
    Some(out)
}

/// f64 → 16 lowercase hex chars of its IEEE754 bit pattern (the σ-as-bits
/// law: doubles travel as BITS, never as decimal text).
fn f64_to_hex16(d: f64) -> String {
    format!("{:016x}", d.to_bits())
}

fn hex16_to_f64(s: &str) -> Option<f64> {
    let u = u64::from_str_radix(s, 16).ok()?;
    Some(f64::from_bits(u))
}

struct Counters {
    total: usize,
    failures: usize,
}

fn run_vector_case(
    counters: &mut Counters,
    id: &str,
    rows: usize,
    cols: usize,
    whex: &[u8],
    xline: &str,
    outline: &str,
) {
    let Some(w) = hex_to_bytes(whex, rows * cols) else {
        println!("VEC {id} FAIL bad-hex");
        counters.failures += 1;
        return;
    };
    // X line: "X v1,v2,…" (prefix already stripped by the caller)
    let xs: Vec<i64> = xline
        .split([',', ' '])
        .filter(|s| !s.is_empty())
        .map(|s| s.trim().parse::<i64>().expect("bad X integer"))
        .collect();
    if xs.len() != cols {
        println!("VEC {id} FAIL xs-count");
        counters.failures += 1;
        return;
    }
    let (re, im) = vector_pass(&w, rows, cols, &xs);
    // OUT line: "OUT r1,r2,…|i1,i2,…"
    let (expect_re, expect_im) = outline
        .split_once('|')
        .expect("OUT line must carry re|im");
    let parse = |s: &str| -> Vec<i64> {
        s.split([',', ' '])
            .filter(|t| !t.is_empty())
            .map(|t| t.trim().parse::<i64>().expect("bad OUT integer"))
            .collect()
    };
    let er = parse(expect_re);
    let ei = parse(expect_im);
    let ok = er == re && ei == im;
    counters.total += 1;
    if ok {
        println!("VEC {id} PASS");
    } else {
        println!("VEC {id} FAIL re/im mismatch");
        counters.failures += 1;
    }
}

#[allow(clippy::too_many_arguments)]
fn run_substrate_case(
    counters: &mut Counters,
    id: &str,
    w: i32,
    h: i32,
    t_ticks: i32,
    is_fixed: bool,
    wormholes: bool,
    sigma_kind: &str,
    sigma_hex: &str,
    init_plane: &[u8],
    hash_expect: &str,
    events_expect: &[(i32, i32, i32, i32, i32, String)],
) {
    let mut s = Substrate::new(w, h, init_plane);
    let mut events = Vec::new();
    let sigma_d = if sigma_kind == "bits" {
        hex16_to_f64(sigma_hex)
    } else {
        None
    };
    let sigma_q = if sigma_kind == "q" {
        u64::from_str_radix(sigma_hex, 16).ok()
    } else {
        None
    };

    for t in 1..=t_ticks {
        if is_fixed {
            qthe::tick_fixed(&mut s, wormholes, sigma_q.unwrap_or(0), &mut events);
        } else {
            qthe::tick(&mut s, wormholes, sigma_d, &mut events);
        }
        // The event TICK is set inside the kernel as (ticks+1) — the 1-based
        // loop index `t` the fixtures record; compared below (stricter than
        // the C runner by exactly this one field).
        debug_assert!(events.last().map_or(true, |e| e.tick == t));
    }

    let mut ok = true;
    let mut why = String::new();
    if events.len() != events_expect.len() {
        ok = false;
        why = format!("event-count {} != {}", events.len(), events_expect.len());
    } else {
        for (i, ev) in events.iter().enumerate() {
            let (et, ex, ey, eslot, eres, eterm) = &events_expect[i];
            if ev.tick != *et || ev.x != *ex || ev.y != *ey || ev.slot != *eslot || ev.resonance != *eres
            {
                ok = false;
                why = format!(
                    "event[{i}] tuple ({},{},{},{},{}) != ({et},{ex},{ey},{eslot},{eres})",
                    ev.tick, ev.x, ev.y, ev.slot, ev.resonance
                );
                break;
            }
            if is_fixed {
                if ev.term_q.to_string() != *eterm {
                    ok = false;
                    why = format!("event[{i}] term_q {} != {eterm}", ev.term_q);
                    break;
                }
            } else if f64_to_hex16(ev.term) != *eterm {
                ok = false;
                why = format!(
                    "event[{i}] term bits {} != {eterm}",
                    f64_to_hex16(ev.term)
                );
                break;
            }
        }
    }
    let hash = s.plane_hash(t_ticks as i64);
    if ok && hash != hash_expect {
        ok = false;
        why = format!("plane-hash {hash} != {hash_expect}");
    }
    counters.total += 1;
    if ok {
        println!("CASE {id} PASS");
    } else {
        println!("CASE {id} FAIL ({why})");
        counters.failures += 1;
    }
}

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("usage: {} <fixtures.txt>", args[0]);
        return ExitCode::from(2);
    }
    let data = match fs::read(&args[1]) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("fixtures read error: {e}");
            return ExitCode::from(2);
        }
    };
    let mut lines = BufReader::new(&data[..]).lines().map(|l| l.unwrap());

    let Some(first) = lines.next() else {
        eprintln!("empty fixtures file");
        return ExitCode::from(2);
    };
    if !first.starts_with("QTHEFIX") {
        eprintln!("bad magic");
        return ExitCode::from(2);
    }

    let mut counters = Counters { total: 0, failures: 0 };
    let mut plane: Vec<u8>;

    while let Some(line) = lines.next() {
        let l = line.trim();
        if l.is_empty() || l.starts_with('#') {
            continue;
        }
        if let Some(rest) = l.strip_prefix("VEC ") {
            let mut it = rest.split_whitespace();
            let id = it.next().unwrap_or("?").to_string();
            let rows: usize = it.next().and_then(|v| v.parse().ok()).unwrap_or(0);
            let cols: usize = it.next().and_then(|v| v.parse().ok()).unwrap_or(0);
            let whex = lines.next().expect("W line");
            let xline = lines.next().expect("X line");
            let outline = lines.next().expect("OUT line");
            run_vector_case(
                &mut counters,
                &id,
                rows,
                cols,
                whex.trim().split_once(' ').map(|(_, h)| h.as_bytes()).unwrap_or(b""),
                xline.trim().split_once(' ').map(|(_, h)| h).unwrap_or(""),
                outline.trim().strip_prefix("OUT ").unwrap_or(outline.trim()),
            );
        } else if let Some(rest) = l.strip_prefix("CASE ") {
            let mut it = rest.split_whitespace();
            let id = it.next().unwrap_or("?").to_string();
            let w: i32 = it.next().and_then(|v| v.parse().ok()).unwrap_or(0);
            let h: i32 = it.next().and_then(|v| v.parse().ok()).unwrap_or(0);
            let t_ticks: i32 = it.next().and_then(|v| v.parse().ok()).unwrap_or(0);
            let mode = it.next().unwrap_or("float").to_string();
            let wh: i32 = it.next().and_then(|v| v.parse().ok()).unwrap_or(1);
            let skind = it.next().unwrap_or("default").to_string();
            let shex = it.next().unwrap_or("-").to_string();

            let pline = lines.next().expect("PLANE line");
            let pline = pline.trim();
            let pbody = pline.strip_prefix("PLANE ").unwrap_or(pline);
            plane = match hex_to_bytes(pbody.as_bytes(), (w * h) as usize) {
                Some(p) => p,
                None => {
                    println!("CASE {id} FAIL plane");
                    counters.failures += 1;
                    continue;
                }
            };

            let eline = lines.next().expect("EVENTS line");
            let n_ev: usize = eline
                .trim()
                .strip_prefix("EVENTS ")
                .and_then(|v| v.parse().ok())
                .unwrap_or(0);
            let mut events_expect = Vec::with_capacity(n_ev);
            for _ in 0..n_ev {
                let ev = lines.next().expect("E line");
                let mut it = ev.trim().strip_prefix("E ").unwrap_or(ev.trim()).split_whitespace();
                let t: i32 = it.next().and_then(|v| v.parse().ok()).unwrap_or(0);
                let x: i32 = it.next().and_then(|v| v.parse().ok()).unwrap_or(0);
                let y: i32 = it.next().and_then(|v| v.parse().ok()).unwrap_or(0);
                let slot: i32 = it.next().and_then(|v| v.parse().ok()).unwrap_or(0);
                let res: i32 = it.next().and_then(|v| v.parse().ok()).unwrap_or(0);
                let term = it.next().unwrap_or("").to_string();
                events_expect.push((t, x, y, slot, res, term));
            }
            let hash_line = lines.next().expect("HASH line");
            let hash_expect = hash_line
                .trim()
                .strip_prefix("HASH ")
                .unwrap_or(hash_line.trim())
                .to_string();
            let _end = lines.next().expect("END line");

            run_substrate_case(
                &mut counters,
                &id,
                w,
                h,
                t_ticks,
                mode == "fixed",
                wh != 0,
                &skind,
                &shex,
                &plane,
                &hash_expect,
                &events_expect,
            );
        }
    }

    println!(
        "\nconformance: {}/{} cases PASS, {} FAIL",
        counters.total - counters.failures,
        counters.total,
        counters.failures
    );
    ExitCode::from(counters.failures as u8)
}
